function MenuItemPreview({
  name,
  price,
  emoji,
  isNew = false,
  isChefPick = false
}: {
  name: string
  price: string
  emoji: string
  isNew?: boolean
  isChefPick?: boolean
}) {
  return (
    <div className="flex items-center gap-3 p-3 bg-secondary-50 dark:bg-secondary-900/50 rounded-xl">
